STATUS = {200: "OK", 201: "Created", 204: "No Content",
          400: "Bad Request", 401: "Unauthorized",
          403: "Forbidden", 404: "Not Found",
          500: "Internal Server Error"}

def describe(method, code):
    return f"{method:6s}  {code}  {STATUS.get(code, '?')}"

pairs = [("GET", 200), ("POST", 201), ("PUT", 204),
         ("DELETE", 404), ("PATCH", 400)]
for method, code in pairs:
    print(describe(method, code))
